```html
<!doctype html>
<html lang="zh-Hant">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta name="color-scheme" content="light" />
  <title>品牌策略工作坊｜活動報名流程原型</title>
  <style>
    :root{
      --bg:#f4f1eb;
      --paper:#fffdf8;
      --paper-2:#f8f5ee;
      --ink:#1f2926;
      --muted:#58645f;
      --line:#d8ddd7;
      --brand:#17483c;
      --brand-2:#246454;
      --accent:#d8a849;
      --soft-green:#e6efe9;
      --soft-yellow:#fbf1d7;
      --soft-red:#f6e5e0;
      --danger:#8c3b2f;
      --success:#246147;
      --shadow:0 22px 70px rgba(29,49,41,.08);
      --radius:24px;
      --max:1180px;
    }

    *{box-sizing:border-box}
    html{scroll-behavior:smooth}

    body{
      margin:0;
      background:
        radial-gradient(circle at top right,rgba(216,168,73,.10),transparent 30rem),
        var(--bg);
      color:var(--ink);
      font-family:
        -apple-system,BlinkMacSystemFont,"Segoe UI",
        "Noto Sans TC","PingFang TC","Microsoft JhengHei",sans-serif;
      font-size:18px;
      line-height:1.75;
    }

    button,input,select,textarea{font:inherit}

    button{cursor:pointer}

    button:disabled{
      cursor:not-allowed;
      opacity:.48;
      filter:grayscale(.2);
    }

    a{color:inherit}
    strong{font-weight:800}

    .wrap{
      width:min(calc(100% - 48px),var(--max));
      margin:auto;
    }

    .prototype-bar{
      background:#17211e;
      color:#fff;
      padding:14px 20px;
      text-align:center;
      font-size:16px;
      font-weight:700;
      letter-spacing:.02em;
    }

    header{
      position:relative;
      z-index:20;
      background:rgba(244,241,235,.94);
      backdrop-filter:blur(16px);
      border-bottom:1px solid rgba(31,41,38,.08);
    }

    nav{
      min-height:76px;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:20px;
    }

    .brand{
      display:flex;
      align-items:center;
      gap:12px;
      font-size:18px;
      font-weight:900;
      text-decoration:none;
    }

    .brand-mark{
      width:38px;
      height:38px;
      display:grid;
      place-items:center;
      flex:0 0 auto;
      border-radius:12px;
      background:var(--brand);
      color:#fff;
      font-weight:900;
    }

    .nav-links{
      display:flex;
      gap:24px;
      align-items:center;
      flex-wrap:wrap;
    }

    .nav-links a{
      text-decoration:none;
      color:var(--muted);
      font-size:16px;
      font-weight:700;
    }

    .button,
    button{
      min-height:52px;
      border:0;
      border-radius:14px;
      padding:12px 20px;
      font-size:16px;
      font-weight:800;
      transition:.2s ease;
    }

    .button{
      display:inline-flex;
      align-items:center;
      justify-content:center;
      text-decoration:none;
    }

    .primary{
      background:var(--brand);
      color:#fff;
      box-shadow:0 8px 28px rgba(23,72,60,.18);
    }

    .primary:hover:not(:disabled){
      background:var(--brand-2);
      transform:translateY(-1px);
    }

    .secondary{
      background:#fff;
      color:var(--brand);
      border:1px solid var(--line);
    }

    .secondary:hover:not(:disabled){background:var(--paper-2)}

    .warning{
      background:#7c4b22;
      color:#fff;
    }

    .danger{
      background:#7c352d;
      color:#fff;
    }

    .ghost{
      background:transparent;
      color:var(--brand);
      border:1px solid #aac0b6;
    }

    main{overflow:hidden}

    .hero{
      padding:96px 0 82px;
    }

    .hero-grid{
      display:grid;
      grid-template-columns:minmax(0,1.15fr) minmax(320px,.85fr);
      gap:64px;
      align-items:center;
    }

    .eyebrow,
    .tag{
      display:inline-flex;
      align-items:center;
      gap:8px;
      border-radius:999px;
      padding:8px 13px;
      font-size:16px;
      line-height:1.3;
      font-weight:800;
    }

    .eyebrow{
      background:var(--soft-green);
      color:var(--brand);
      margin-bottom:22px;
    }

    h1,h2,h3,p{margin-top:0}

    h1{
      margin-bottom:24px;
      max-width:800px;
      font-size:clamp(48px,7vw,82px);
      line-height:1.02;
      letter-spacing:-.05em;
    }

    h2{
      margin-bottom:18px;
      font-size:clamp(36px,5vw,54px);
      line-height:1.1;
      letter-spacing:-.035em;
    }

    h3{
      margin-bottom:12px;
      font-size:24px;
      line-height:1.35;
    }

    .lead{
      max-width:780px;
      color:var(--muted);
      font-size:22px;
      line-height:1.75;
    }

    .hero-actions{
      display:flex;
      flex-wrap:wrap;
      gap:12px;
      margin-top:32px;
    }

    .hero-facts{
      display:grid;
      grid-template-columns:repeat(3,1fr);
      gap:20px;
      margin-top:48px;
    }

    .fact{
      border-top:1px solid #cdd4d0;
      padding-top:16px;
    }

    .fact-label{
      color:var(--muted);
      font-size:16px;
      font-weight:700;
    }

    .fact-value{
      margin-top:6px;
      font-size:18px;
      font-weight:900;
    }

    .hero-card{
      position:relative;
      background:var(--brand);
      color:#fff;
      border-radius:32px;
      padding:40px;
      box-shadow:var(--shadow);
      overflow:hidden;
    }

    .hero-card::after{
      content:"";
      position:absolute;
      width:250px;
      height:250px;
      right:-90px;
      top:-80px;
      border-radius:50%;
      border:50px solid rgba(255,255,255,.06);
    }

    .hero-card .tag{
      background:rgba(255,255,255,.12);
      color:#fff;
      position:relative;
      z-index:1;
    }

    .hero-card h3{
      font-size:34px;
      margin-top:30px;
      margin-bottom:14px;
      position:relative;
      z-index:1;
    }

    .hero-card p{
      position:relative;
      z-index:1;
      color:rgba(255,255,255,.78);
      margin-bottom:0;
    }

    .seat-meter{
      margin-top:34px;
      position:relative;
      z-index:1;
    }

    .meter-row{
      display:flex;
      justify-content:space-between;
      gap:12px;
      font-size:16px;
      font-weight:800;
    }

    .meter{
      height:12px;
      margin-top:12px;
      border-radius:999px;
      background:rgba(255,255,255,.16);
      overflow:hidden;
    }

    .meter > span{
      display:block;
      width:90%;
      height:100%;
      background:#efc86e;
      border-radius:inherit;
    }

    section{
      padding:88px 0;
    }

    section + section{
      border-top:1px solid rgba(31,41,38,.08);
    }

    .section-head{
      display:grid;
      grid-template-columns:minmax(0,.85fr) minmax(280px,1.15fr);
      gap:56px;
      margin-bottom:44px;
      align-items:end;
    }

    .section-head p{
      color:var(--muted);
      margin-bottom:4px;
      max-width:720px;
    }

    .overline{
      display:block;
      margin-bottom:12px;
      color:var(--brand);
      font-size:16px;
      font-weight:900;
      letter-spacing:.08em;
      text-transform:uppercase;
    }

    .card{
      background:var(--paper);
      border:1px solid rgba(31,41,38,.09);
      border-radius:var(--radius);
      box-shadow:0 12px 35px rgba(29,49,41,.04);
    }

    .evidence-grid{
      display:grid;
      grid-template-columns:1fr 1fr;
      gap:22px;
    }

    .evidence{
      padding:34px;
      min-height:250px;
    }

    .muted{color:var(--muted)}

    .note{
      font-size:16px;
      color:var(--muted);
    }

    .info-grid{
      display:grid;
      grid-template-columns:1fr 1fr;
      gap:22px;
    }

    .info-card{
      padding:36px;
    }

    .info-list{
      display:grid;
      gap:0;
      margin:0;
    }

    .info-row{
      display:grid;
      grid-template-columns:150px 1fr;
      gap:24px;
      padding:20px 0;
      border-bottom:1px solid var(--line);
    }

    .info-row:last-child{border-bottom:0}
    .info-row dt{font-weight:900}
    .info-row dd{margin:0;color:var(--muted)}

    .agenda{
      display:grid;
      gap:0;
      margin-top:20px;
    }

    .agenda-item{
      display:grid;
      grid-template-columns:120px 1fr;
      gap:24px;
      padding:20px 0;
      border-bottom:1px solid var(--line);
    }

    .agenda-item:last-child{border-bottom:0}

    .agenda-time{
      font-weight:900;
      color:var(--brand);
    }

    .ticket-grid{
      display:grid;
      grid-template-columns:repeat(3,1fr);
      gap:22px;
    }

    .ticket{
      position:relative;
      display:flex;
      flex-direction:column;
      padding:34px;
    }

    .ticket.active{
      outline:3px solid rgba(23,72,60,.18);
      border-color:var(--brand);
    }

    .ticket.sold-out{
      background:#f2f0ec;
    }

    .ticket .tag{
      align-self:flex-start;
      background:var(--soft-yellow);
      color:#6d4a10;
    }

    .ticket-price{
      margin:28px 0 6px;
      font-size:42px;
      line-height:1;
      font-weight:900;
      letter-spacing:-.04em;
    }

    .ticket-meta{
      display:grid;
      gap:10px;
      margin:28px 0;
      padding:20px 0;
      border-top:1px solid var(--line);
      border-bottom:1px solid var(--line);
      color:var(--muted);
      font-size:16px;
    }

    .ticket-actions{
      display:grid;
      gap:10px;
      margin-top:auto;
    }

    .state-layout{
      display:grid;
      grid-template-columns:.92fr 1.08fr;
      gap:22px;
    }

    .status-panel,
    .simulation-panel{
      padding:36px;
    }

    .status-badge{
      display:inline-flex;
      border-radius:999px;
      padding:8px 14px;
      background:var(--soft-yellow);
      color:#67460f;
      font-size:16px;
      font-weight:900;
    }

    .status-badge.success{
      background:var(--soft-green);
      color:var(--success);
    }

    .status-badge.danger{
      background:var(--soft-red);
      color:var(--danger);
    }

    .steps{
      display:grid;
      gap:10px;
      margin-top:30px;
    }

    .step{
      display:grid;
      grid-template-columns:42px 1fr;
      gap:16px;
      align-items:flex-start;
      padding:18px;
      border-radius:16px;
      background:var(--paper-2);
    }

    .step-no{
      width:42px;
      height:42px;
      display:grid;
      place-items:center;
      border-radius:50%;
      background:#e6eae7;
      font-weight:900;
    }

    .step.current{
      background:var(--soft-green);
    }

    .step.current .step-no{
      background:var(--brand);
      color:#fff;
    }

    .controls{
      display:flex;
      flex-wrap:wrap;
      gap:10px;
      margin-top:22px;
    }

    .notification{
      padding:20px 22px;
      border-radius:16px;
      background:var(--paper-2);
      border-left:5px solid var(--brand);
      margin-top:22px;
    }

    .notification strong{display:block}

    .rule-grid{
      display:grid;
      grid-template-columns:repeat(2,1fr);
      gap:22px;
    }

    .rule-card{
      padding:34px;
    }

    .waitlist-box{
      display:grid;
      grid-template-columns:.9fr 1.1fr;
      gap:22px;
      margin-top:28px;
    }

    .queue,
    .waitlist-form{
      padding:34px;
    }

    .queue-list{
      display:grid;
      gap:12px;
      margin-top:20px;
    }

    .queue-item{
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:16px;
      padding:18px;
      border-radius:14px;
      background:var(--paper-2);
    }

    .queue-rank{
      min-width:48px;
      height:48px;
      display:grid;
      place-items:center;
      border-radius:50%;
      background:var(--brand);
      color:#fff;
      font-weight:900;
    }

    .notification-grid{
      display:grid;
      grid-template-columns:repeat(2,1fr);
      gap:18px;
    }

    .notification-card{
      padding:30px;
    }

    .form-layout{
      display:grid;
      grid-template-columns:1.1fr .9fr;
      gap:22px;
    }

    form.card,
    .summary-card{
      padding:36px;
    }

    .fields{
      display:grid;
      grid-template-columns:repeat(2,1fr);
      gap:22px;
    }

    .field{
      display:grid;
      gap:8px;
    }

    .field.full{grid-column:1/-1}

    label,
    legend{
      font-size:18px;
      font-weight:800;
    }

    input,
    select,
    textarea{
      width:100%;
      min-height:56px;
      border:1px solid #bcc6c1;
      border-radius:13px;
      background:#fff;
      color:var(--ink);
      padding:13px 15px;
      outline:none;
    }

    textarea{
      min-height:140px;
      resize:vertical;
    }

    input:focus,
    select:focus,
    textarea:focus{
      border-color:var(--brand);
      box-shadow:0 0 0 4px rgba(23,72,60,.10);
    }

    .check-row{
      display:grid;
      grid-template-columns:24px 1fr;
      gap:12px;
      align-items:start;
    }

    .check-row input{
      width:22px;
      min-height:22px;
      margin-top:6px;
    }

    .validation{
      min-height:28px;
      margin:12px 0 0;
      color:var(--danger);
      font-size:16px;
      font-weight:700;
    }

    .summary-list{
      display:grid;
      gap:16px;
      margin-top:26px;
    }

    .summary-row{
      display:flex;
      justify-content:space-between;
      gap:18px;
      padding-bottom:15px;
      border-bottom:1px solid var(--line);
    }

    .summary-row span:first-child{color:var(--muted)}

    .data-section{
      background:#ebe8e1;
    }

    .table-wrap{
      overflow:auto;
      border-radius:20px;
      border:1px solid rgba(31,41,38,.10);
      background:#fff;
      margin-top:20px;
    }

    table{
      width:100%;
      min-width:850px;
      border-collapse:collapse;
      font-size:16px;
    }

    th,
    td{
      padding:18px;
      text-align:left;
      vertical-align:top;
      border-bottom:1px solid var(--line);
      overflow-wrap:anywhere;
    }

    th{
      background:#f1f3f0;
      color:#37433e;
      font-weight:900;
    }

    tr:last-child td{border-bottom:0}

    details{
      background:#fff;
      border:1px solid rgba(31,41,38,.09);
      border-radius:18px;
      margin-top:16px;
      overflow:hidden;
    }

    summary{
      cursor:pointer;
      padding:22px 24px;
      font-weight:900;
    }

    details > div{
      padding:0 24px 24px;
    }

    .log{
      max-height:440px;
      overflow:auto;
      padding:0;
      margin:24px 0 0;
      list-style:none;
    }

    .log li{
      padding:16px 0;
      border-bottom:1px solid var(--line);
    }

    .log li:last-child{border-bottom:0}

    .log-time{
      display:block;
      color:var(--muted);
      font-size:16px;
    }

    .footer{
      padding:54px 0 76px;
      color:var(--muted);
    }

    .footer-grid{
      display:grid;
      grid-template-columns:1fr auto;
      gap:28px;
      align-items:end;
    }

    .danger-zone{
      padding:30px;
      background:#fff7f4;
      border:1px solid #e5c7bf;
      border-radius:20px;
      margin-top:36px;
    }

    .sr-only{
      position:absolute;
      width:1px;
      height:1px;
      padding:0;
      margin:-1px;
      overflow:hidden;
      clip:rect(0,0,0,0);
      white-space:nowrap;
      border:0;
    }

    .site-header,
    header{
      position:relative!important;
    }

    .starter{padding:56px 0;background:#e7ebe3}
    .starter-layout{display:grid;grid-template-columns:1fr 1.15fr;gap:32px;align-items:stretch}
    .starter-form,.starter-preview{padding:32px;border-radius:24px;background:#fffdf8;border:1px solid #c8d0c8}
    .starter-form{display:grid;gap:18px}
    .starter-form label{display:grid;gap:8px}
    .starter-preview{background:#17483c;color:white;display:flex;flex-direction:column;justify-content:center}
    .starter-preview h3{font-size:40px;line-height:1.25;overflow-wrap:anywhere}
    .starter-preview p{font-size:20px;color:#f1eee3;overflow-wrap:anywhere}
    .starter-preview small{font-size:16px;color:#d7ddd6}
    .starter-preview hr{width:100%;border:0;border-top:1px solid #668276;margin:18px 0}
    .starter input{width:100%;min-width:0;font-size:18px;padding:12px;border:1px solid #9dac9e;border-radius:10px}
    .starter h2{font-size:40px}
    .starter label{font-size:18px}

    @media(max-width:900px){
      .nav-links a:not(.button){display:none}

      .hero-grid,
      .section-head,
      .state-layout,
      .waitlist-box,
      .form-layout{
        grid-template-columns:1fr;
      }

      .hero-card{max-width:620px}

      .evidence-grid,
      .ticket-grid{
        grid-template-columns:1fr;
      }

      .info-grid,
      .rule-grid,
      .notification-grid{
        grid-template-columns:1fr;
      }
    }

    @media(max-width:640px){
      body{
        font-size:18px;
        line-height:1.72;
      }

      .wrap{
        width:min(calc(100% - 28px),var(--max));
      }

      header{
        position:relative!important;
      }

      nav{
        min-height:68px;
      }

      .brand span:last-child{display:none}

      .prototype-bar,
      .tag,
      .eyebrow,
      .nav-links a,
      .fact-label,
      .status-badge,
      .log-time,
      button,
      .button{
        font-size:16px;
      }

      .note,
      .ticket-meta{
        font-size:18px;
      }

      .hero{
        padding:58px 0 56px;
      }

      .hero-grid{
        gap:34px;
      }

      h1{
        font-size:48px;
        line-height:1.05;
      }

      h2{
        font-size:32px;
        line-height:1.15;
      }

      h3{
        font-size:24px;
      }

      .section-head h2{
        font-size:32px;
      }

      .lead{
        font-size:20px;
      }

      section{
        padding:60px 0;
      }

      .section-head{
        gap:18px;
        margin-bottom:30px;
      }

      .section-head p,
      p,
      .muted,
      .info-row dd,
      .agenda-item,
      .summary-row,
      details > div,
      .notification,
      .queue-item,
      label,
      legend,
      input,
      select,
      textarea{
        font-size:18px;
      }

      .hero-facts{
        grid-template-columns:1fr;
        gap:18px;
        margin-top:38px;
      }

      .hero-card,
      .card,
      form.card,
      .summary-card{
        border-radius:20px;
      }

      .hero-card,
      .info-card,
      .ticket,
      .status-panel,
      .simulation-panel,
      .rule-card,
      .queue,
      .waitlist-form,
      .notification-card,
      form.card,
      .summary-card{
        padding:24px;
      }

      .evidence{
        padding:24px;
        min-height:auto;
      }

      .fields{
        grid-template-columns:1fr;
      }

      .info-row,
      .agenda-item{
        grid-template-columns:1fr;
        gap:4px;
      }

      .hero-actions,
      .controls{
        display:grid;
      }

      .hero-actions > *,
      .controls > *,
      .ticket-actions > *{
        width:100%;
      }

      .summary-row{
        display:grid;
        gap:2px;
      }

      .footer-grid{
        grid-template-columns:1fr;
      }

      .table-wrap,
      .table-scroll{
        overflow:visible!important;
        border:0;
        background:transparent;
      }

      table{
        min-width:0!important;
        width:100%!important;
        display:block;
        font-size:18px;
      }

      thead{
        position:absolute;
        width:1px;
        height:1px;
        overflow:hidden;
        clip-path:inset(50%);
        white-space:nowrap;
      }

      tbody{
        display:grid;
        gap:18px;
        width:100%;
      }

      tr{
        display:block;
        width:100%;
        border:1px solid var(--line,#d4cec1);
        border-radius:18px;
        padding:18px;
        margin:0;
        background:var(--paper,#fffdf8);
        box-shadow:0 8px 24px rgba(29,49,41,.04);
      }

      td{
        display:grid!important;
        grid-template-columns:1fr;
        gap:2px;
        min-width:0!important;
        width:auto!important;
        border:0!important;
        border-bottom:1px solid var(--line)!important;
        padding:12px 0!important;
        overflow-wrap:anywhere;
        font-size:18px!important;
        line-height:1.65;
      }

