              </div>
              <div class="info-row">
                <dt>主辦單位</dt>
                <dd>教學示例工作室</dd>
              </div>
              <div class="info-row">
                <dt>活動狀態</dt>
                <dd>教學示例：開放報名</dd>
              </div>
