        </div>

        <div class="form-layout">
          <form id="registrationForm" class="card" novalidate>
            <div class="fields">
              <div class="field">
                <label for="name">姓名</label>
                <input id="name" name="name" autocomplete="name" required placeholder="請輸入姓名" />
