      /*
        手機表格轉換為逐筆卡片：
        保留原本 table、thead、tbody、tr、td 結構，
        並利用既有 JavaScript 加上的 data-label
        在每個儲存格前顯示對應欄位名稱。
      */

      .table-wrap,
      .table-scroll {
        overflow: visible !important;
        width: 100%;
        max-width: 100%;
        border: 0;
        border-radius: 0;
        background: transparent;
        box-shadow: none;
        margin-top: 22px;
      }

      table {
        display: block;
        width: 100% !important;
        min-width: 0 !important;
        border-collapse: separate;
        font-size: 18px;
      }

      thead {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip-path: inset(50%);
        white-space: nowrap;
        border: 0;
      }

      tbody {
        display: grid;
        width: 100%;
        gap: 18px;
      }

      tr {
        display: block;
        width: 100%;
        min-width: 0;
        margin: 0;
        padding: 22px;
        border: 1px solid var(--line);
        border-radius: 18px;
        background: var(--paper);
        box-shadow: 0 8px 24px rgba(29, 49, 41, .05);
      }

      tbody tr:nth-child(even) {
        background: var(--paper);
      }

      td {
        display: grid !important;
        grid-template-columns: minmax(0, 1fr);
        gap: 6px;
        min-width: 0 !important;
        width: 100% !important;
        max-width: 100%;
        padding: 16px 0 !important;
        border: 0 !important;
        border-bottom: 1px solid var(--line) !important;
        background: transparent;
        font-size: 18px !important;
        line-height: 1.75;
        text-align: left;
        overflow-wrap: anywhere;
        word-break: normal;
        white-space: normal;
      }

      td:first-child {
        padding-top: 0 !important;
      }

      td:last-child {
        padding-bottom: 0 !important;
        border-bottom: 0 !important;
      }

      td[data-label]::before {
        content: attr(data-label);
        display: block;
        margin-bottom: 2px;
        color: var(--muted);
        font-size: 16px;
        line-height: 1.5;
        font-weight: 900;
      }

      td[colspan] {
        display: block !important;
        min-height: auto;
        padding: 0 !important;
        border-bottom: 0 !important;
      }

      td[colspan][data-label]::before {
        margin-bottom: 10px;
      }

      .data-section h3 {
        margin-top: 0;
        margin-bottom: 18px;
      }

      .data-section h3[style] {
        margin-top: 44px !important;
      }

      .data-section .card[style] {
        padding: 28px !important;
        margin-top: 44px !important;
      }

      .log {
        margin-top: 24px;
      }

      .log li {
        padding: 20px 0;
      }

      .log-time {
        font-size: 16px;
      }

      .danger-zone {
        padding: 28px;
        margin-top: 36px;
      }

      .danger-zone button {
        width: 100%;
      }

      .starter {
        padding: 68px 0;
      }

      .starter h2 {
        margin-bottom: 30px;
        font-size: 32px;
        line-height: 1.22;
      }

      .starter-layout {
        grid-template-columns: minmax(0, 1fr);
        gap: 20px;
      }

      .starter-form,
      .starter-preview {
        padding: 28px;
        border-radius: 20px;
      }

      .starter-form {
        gap: 24px;
      }

      .starter-preview {
        min-height: 280px;
      }

      .starter-preview h3 {
        font-size: 32px;
        line-height: 1.35;
        margin: 20px 0;
      }

      .starter-preview p {
        font-size: 20px;
        line-height: 1.8;
      }

      .starter-preview small {
        font-size: 16px;
      }

      .starter label,
      .starter input {
        font-size: 18px;
      }

      .footer {
        padding: 56px 0 72px;
      }

      .footer-grid {
        grid-template-columns: minmax(0, 1fr);
        gap: 28px;
      }

      .footer .button {
        width: 100%;
      }
    }

    @media (max-width: 380px) {
      .wrap {
        width: min(calc(100% - 28px), var(--max));
      }

      .hero-card,
      .info-card,
      .ticket,
      .status-panel,
      .simulation-panel,
      .rule-card,
      .queue,
      .waitlist-form,
      .notification-card,
      form.card,
      .summary-card,
      .evidence,
      .starter-form,
      .starter-preview {
        padding: 22px;
      }

