      line-height: 1.2;
      letter-spacing: -.035em;
      overflow-wrap: anywhere;
    }

    h3 {
      margin-bottom: 18px;
      font-size: 25px;
      line-height: 1.4;
      overflow-wrap: anywhere;
    }

    .wrap {
      width: min(calc(100% - 64px), var(--max));
      margin-inline: auto;
    }

    .muted {
      color: var(--muted);
    }

    .note {
      font-size: 16px;
      line-height: 1.7;
      color: var(--muted);
    }

    .overline {
      display: block;
      margin-bottom: 16px;
      color: var(--brand);
      font-size: 16px;
      font-weight: 900;
      line-height: 1.5;
      letter-spacing: .08em;
      text-transform: uppercase;
    }

    .prototype-bar {
      background: #17211e;
      color: #fff;
      padding: 16px 24px;
      text-align: center;
      font-size: 16px;
      line-height: 1.65;
      font-weight: 700;
      letter-spacing: .02em;
    }

    header,
    .site-header {
      position: relative !important;
    }

    header {
      z-index: 20;
      background: rgba(244, 241, 235, .94);
      backdrop-filter: blur(16px);
      border-bottom: 1px solid rgba(31, 41, 38, .08);
    }

    nav {
      min-height: 80px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 28px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 14px;
      min-width: 0;
      font-size: 18px;
      font-weight: 900;
      text-decoration: none;
    }

    .brand-mark {
      width: 42px;
      height: 42px;
      display: grid;
      place-items: center;
      flex: 0 0 auto;
      border-radius: 12px;
      background: var(--brand);
      color: #fff;
      font-weight: 900;
    }

    .nav-links {
      display: flex;
      gap: 28px;
      align-items: center;
      justify-content: flex-end;
      flex-wrap: wrap;
    }

    .nav-links a {
      text-decoration: none;
      color: var(--muted);
      font-size: 16px;
      font-weight: 700;
    }

    .nav-links .button {
      color: #fff;
    }

    .nav-links a:not(.button):hover {
      color: var(--brand);
    }

    .button,
    button {
      min-height: 54px;
      border: 0;
      border-radius: 14px;
      padding: 13px 22px;
      font-size: 16px;
      line-height: 1.5;
      font-weight: 800;
      text-align: center;
      transition:
        background-color .2s ease,
        border-color .2s ease,
        transform .2s ease;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      text-decoration: none;
    }

    .primary {
      background: var(--brand);
      color: #fff;
      box-shadow: 0 8px 28px rgba(23, 72, 60, .18);
    }

    .primary:hover:not(:disabled) {
      background: var(--brand-2);
      transform: translateY(-1px);
    }

    .secondary {
      background: #fff;
      color: var(--brand);
      border: 1px solid var(--line);
    }

    .secondary:hover:not(:disabled) {
      background: var(--paper-2);
    }

    .warning {
      background: #7c4b22;
      color: #fff;
    }

    .danger {
      background: #7c352d;
      color: #fff;
    }

    .ghost {
      background: transparent;
      color: var(--brand);
      border: 1px solid #aac0b6;
    }

    a:focus-visible,
    button:focus-visible,
    summary:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 4px;
    }

    main {
      overflow: hidden;
    }

    section {
      padding: 100px 0;
    }

    section + section {
      border-top: 1px solid rgba(31, 41, 38, .08);
    }

    .hero {
      padding: 104px 0 100px;
    }

    .hero-grid {
      display: grid;
      grid-template-columns:
        minmax(0, 1.15fr)
        minmax(320px, .85fr);
      gap: 72px;
      align-items: center;
    }

    .hero-grid > *,
    .section-head > *,
    .info-grid > *,
    .ticket-grid > *,
    .state-layout > *,
    .waitlist-box > *,
    .form-layout > *,
    .starter-layout > * {
      min-width: 0;
    }

    .eyebrow,
    .tag {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      max-width: 100%;
      border-radius: 999px;
      padding: 9px 15px;
      font-size: 16px;
      line-height: 1.45;
      font-weight: 800;
    }

    .eyebrow {
      background: var(--soft-green);
      color: var(--brand);
      margin-bottom: 28px;
    }

    .lead {
      max-width: 780px;
      color: var(--muted);
      font-size: 22px;
      line-height: 1.85;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-top: 38px;
    }

    .hero-facts {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 26px;
      margin-top: 60px;
    }

    .fact {
      min-width: 0;
      border-top: 1px solid #cdd4d0;
      padding-top: 20px;
    }

    .fact-label {
      color: var(--muted);
      font-size: 16px;
      line-height: 1.5;
      font-weight: 700;
    }

    .fact-value {
      margin-top: 10px;
      font-size: 18px;
      line-height: 1.55;
      font-weight: 900;
    }

    .hero-card {
      position: relative;
      min-width: 0;
      background: var(--brand);
      color: #fff;
      border-radius: 32px;
      padding: 48px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero-card::after {
      content: "";
      position: absolute;
      width: 250px;
      height: 250px;
      right: -90px;
      top: -80px;
      border-radius: 50%;
      border: 50px solid rgba(255, 255, 255, .06);
      pointer-events: none;
    }

    .hero-card .tag {
      position: relative;
      z-index: 1;
      background: rgba(255, 255, 255, .12);
      color: #fff;
    }

    .hero-card h3 {
      position: relative;
      z-index: 1;
      margin-top: 36px;
      margin-bottom: 22px;
      font-size: 34px;
      line-height: 1.3;
    }

    .hero-card p {
      position: relative;
      z-index: 1;
      color: rgba(255, 255, 255, .88);
      margin-bottom: 0;
      line-height: 1.9;
    }

    .seat-meter {
      position: relative;
      z-index: 1;
      margin-top: 42px;
    }

    .meter-row {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      gap: 12px;
      font-size: 16px;
      line-height: 1.6;
      font-weight: 800;
    }

    .meter {
      height: 12px;
      margin-top: 16px;
      border-radius: 999px;
      background: rgba(255, 255, 255, .16);
      overflow: hidden;
    }

    .meter > span {
      display: block;
      width: 90%;
      height: 100%;
      background: #efc86e;
      border-radius: inherit;
    }

    .section-head {
      display: grid;
      grid-template-columns:
        minmax(0, .95fr)
        minmax(280px, 1.05fr);
      gap: 72px;
      margin-bottom: 52px;
      align-items: end;
    }

    .section-head h2 {
      margin-bottom: 0;
    }

    .section-head p {
      max-width: 720px;
      color: var(--muted);
      margin-bottom: 4px;
      line-height: 1.85;
    }

    .card {
      min-width: 0;
      background: var(--paper);
      border: 1px solid rgba(31, 41, 38, .09);
      border-radius: var(--radius);
      box-shadow: 0 12px 35px rgba(29, 49, 41, .04);
    }

    .card > :last-child {
      margin-bottom: 0;
    }

    .evidence-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 26px;
      align-items: stretch;
    }

    .evidence {
      min-height: 280px;
      padding: 42px;
    }

    .evidence h3 {
      margin-bottom: 18px;
    }

    .evidence p {
      line-height: 1.85;
    }

    .info-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 26px;
      align-items: stretch;
    }

    .info-card {
      padding: 44px;
    }

    .info-card h3 {
      margin-bottom: 24px;
    }

    .info-card p {
      line-height: 1.9;
    }

    .info-list {
      display: grid;
      gap: 0;
      margin: 0;
    }

    .info-row {
      display: grid;
      grid-template-columns: 138px minmax(0, 1fr);
      gap: 28px;
      padding: 24px 0;
      border-bottom: 1px solid var(--line);
    }

    .info-row:last-child {
      border-bottom: 0;
      padding-bottom: 0;
    }

    .info-row dt {
      font-weight: 900;
    }

    .info-row dd {
      margin: 0;
      color: var(--muted);
    }

    .agenda {
      display: grid;
      gap: 0;
      margin-top: 28px;
    }

    .agenda-item {
      display: grid;
      grid-template-columns: 150px minmax(0, 1fr);
      gap: 36px;
      padding: 28px 0;
      border-bottom: 1px solid var(--line);
    }

    .agenda-item:last-child {
      border-bottom: 0;
      padding-bottom: 0;
    }

    .agenda-item strong {
      display: inline-block;
      margin-bottom: 6px;
    }

    .agenda-time {
      color: var(--brand);
      font-weight: 900;
      white-space: nowrap;
    }

    .ticket-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 26px;
      align-items: stretch;
    }

    .ticket {
      position: relative;
      display: flex;
      flex-direction: column;
      padding: 40px 34px;
    }

    .ticket.active {
      outline: 3px solid rgba(23, 72, 60, .18);
      border-color: var(--brand);
    }

    .ticket.sold-out {
      background: #f2f0ec;
    }

    .ticket .tag {
      align-self: flex-start;
      background: var(--soft-yellow);
      color: #6d4a10;
    }

    .ticket h3 {
      margin-bottom: 0;
    }

    .ticket-price {
      margin: 34px 0 12px;
      font-size: clamp(34px, 3.5vw, 42px);
      line-height: 1.2;
      font-weight: 900;
      letter-spacing: -.035em;
      white-space: nowrap;
    }

    .ticket-meta {
      display: grid;
      gap: 14px;
      margin: 34px 0;
      padding: 26px 0;
      border-top: 1px solid var(--line);
      border-bottom: 1px solid var(--line);
      color: var(--muted);
      font-size: 16px;
      line-height: 1.75;
    }

    .ticket-meta strong {
      color: var(--ink);
    }

    .ticket-actions {
      display: grid;
      gap: 12px;
      margin-top: auto;
    }

    .ticket-actions button {
      width: 100%;
    }

    .state-layout {
      display: grid;
      grid-template-columns:
        minmax(0, .92fr)
        minmax(0, 1.08fr);
      gap: 26px;
      align-items: stretch;
    }

    .status-panel,
    .simulation-panel {
      padding: 44px;
    }

    .status-badge {
      display: inline-flex;
      border-radius: 999px;
      padding: 9px 16px;
      background: var(--soft-yellow);
      color: #67460f;
      font-size: 16px;
      font-weight: 900;
    }

    .status-badge.success {
      background: var(--soft-green);
      color: var(--success);
    }

    .status-badge.danger {
      background: var(--soft-red);
      color: var(--danger);
    }

    .steps {
      display: grid;
      gap: 14px;
      margin-top: 36px;
    }

    .step {
      display: grid;
      grid-template-columns: 44px minmax(0, 1fr);
      gap: 18px;
      align-items: flex-start;
      padding: 22px;
      border-radius: 16px;
      background: var(--paper-2);
    }

    .step-no {
      width: 44px;
      height: 44px;
      display: grid;
      place-items: center;
      border-radius: 50%;
      background: #e6eae7;
      font-size: 18px;
      font-weight: 900;
    }

    .step.current {
      background: var(--soft-green);
    }

    .step.current .step-no {
      background: var(--brand);
      color: #fff;
    }

    .step strong {
      display: inline-block;
      margin-bottom: 4px;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 30px;
    }

    .controls button {
      flex: 1 1 210px;
    }

    .notification {
      padding: 24px 28px;
      border-radius: 16px;
      background: var(--paper-2);
      border-left: 5px solid var(--brand);
      margin-top: 30px;
      line-height: 1.85;
      overflow-wrap: anywhere;
    }

    .notification strong {
      display: block;
      margin-bottom: 6px;
    }

    .rule-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 26px;
    }

    .rule-card {
      padding: 42px;
    }

    .rule-card p {
      line-height: 1.9;
    }

    .waitlist-box {
      display: grid;
      grid-template-columns:
        minmax(0, .9fr)
        minmax(0, 1.1fr);
      gap: 26px;
      margin-top: 28px;
      align-items: stretch;
    }

    .queue,
    .waitlist-form {
      padding: 42px;
    }

    .queue-list {
      display: grid;
      gap: 14px;
      margin-top: 28px;
    }

    .queue-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      padding: 22px;
      border-radius: 14px;
      background: var(--paper-2);
    }

    .queue-rank {
      min-width: 48px;
      height: 48px;
      display: grid;
      place-items: center;
      border-radius: 50%;
      background: var(--brand);
      color: #fff;
      font-weight: 900;
    }

    .notification-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 24px;
    }

    .notification-card {
      padding: 38px;
    }

    .notification-card p {
      line-height: 1.9;
    }

    .form-layout {
      display: grid;
      grid-template-columns:
        minmax(0, 1.1fr)
        minmax(0, .9fr);
      gap: 26px;
      align-items: start;
    }

    form.card,
    .summary-card {
      padding: 44px;
    }

    .fields {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 28px 24px;
    }

    .field {
      display: grid;
      gap: 12px;
      min-width: 0;
    }

    .field.full {
      grid-column: 1 / -1;
    }

    label,
    legend {
      font-size: 18px;
      line-height: 1.6;
      font-weight: 800;
    }

    input,
    select,
    textarea {
      width: 100%;
      min-width: 0;
      min-height: 58px;
      border: 1px solid #bcc6c1;
      border-radius: 13px;
      background: #fff;
      color: var(--ink);
      padding: 14px 16px;
      outline: none;
      font-size: 18px;
      line-height: 1.6;
    }

    input::placeholder,
    textarea::placeholder {
      color: #68746e;
      opacity: 1;
    }

    textarea {
      min-height: 160px;
      resize: vertical;
    }

    input:focus,
    select:focus,
    textarea:focus {
      border-color: var(--brand);
      box-shadow: 0 0 0 4px rgba(23, 72, 60, .10);
    }

    .check-row {
      display: grid;
      grid-template-columns: 24px minmax(0, 1fr);
      gap: 16px;
      align-items: start;
      cursor: pointer;
    }

    .check-row input {
      width: 22px;
      min-height: 22px;
      margin: 6px 0 0;
      accent-color: var(--brand);
    }

    .check-row .note {
      display: block;
      margin-top: 6px;
    }

    .validation {
      min-height: 28px;
      margin: 18px 0 12px;
      color: var(--danger);
      font-size: 16px;
      line-height: 1.7;
      font-weight: 700;
    }

    .summary-list {
      display: grid;
      gap: 22px;
      margin-top: 34px;
    }

    .summary-row {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      gap: 12px 20px;
      padding-bottom: 22px;
      border-bottom: 1px solid var(--line);
    }

    .summary-row span:first-child {
      color: var(--muted);
    }

    .summary-row strong {
      text-align: right;
      overflow-wrap: anywhere;
    }

    .data-section {
      background: #ebe8e1;
    }

    .data-section h3 {
      margin-bottom: 20px;
    }

    .table-wrap {
      overflow-x: auto;
      max-width: 100%;
      border-radius: 20px;
      border: 1px solid rgba(31, 41, 38, .10);
      background: #fff;
      margin-top: 24px;
      box-shadow: 0 8px 30px rgba(29, 49, 41, .035);
    }

    table {
      width: 100%;
      min-width: 850px;
      border-collapse: collapse;
      font-size: 16px;
      line-height: 1.8;
    }

    th,
    td {
      padding: 24px 22px;
      text-align: left;
      vertical-align: top;
      border-bottom: 1px solid var(--line);
      overflow-wrap: anywhere;
    }

    th {
      background: #f1f3f0;
      color: #37433e;
      font-weight: 900;
      line-height: 1.55;
    }

    tbody tr:nth-child(even) {
      background: #fafbf8;
    }

    tr:last-child td {
      border-bottom: 0;
    }

    details {
      background: #fff;
      border: 1px solid rgba(31, 41, 38, .09);
      border-radius: 18px;
      margin-top: 20px;
      overflow: hidden;
    }

    summary {
      cursor: pointer;
      padding: 26px 32px;
      font-size: 19px;
      line-height: 1.6;
      font-weight: 900;
    }

    details > div {
      padding: 0 32px 32px;
      line-height: 1.9;
    }

    .log {
      max-height: 440px;
      overflow: auto;
      padding: 0;
      margin: 30px 0 0;
      list-style: none;
    }

    .log li {
      padding: 22px 0;
      border-bottom: 1px solid var(--line);
      overflow-wrap: anywhere;
    }

    .log li:last-child {
      border-bottom: 0;
    }

    .log li strong {
      display: block;
      margin-bottom: 6px;
    }

    .log-time {
      display: block;
      margin-top: 8px;
      color: var(--muted);
      font-size: 16px;
      line-height: 1.65;
    }

    .danger-zone {
      padding: 38px;
      background: #fff7f4;
      border: 1px solid #e5c7bf;
      border-radius: 20px;
      margin-top: 42px;
    }

    .danger-zone p {
      max-width: 900px;
      line-height: 1.85;
    }

    .footer {
      padding: 64px 0 84px;
      color: var(--muted);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 36px;
      align-items: end;
    }

    .footer strong {
      display: block;
      margin-bottom: 12px;
      font-size: 20px;
      color: var(--ink);
    }

    .footer .note {
      max-width: 780px;
      margin-bottom: 0;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .starter {
      padding: 88px 0;
      background: #e7ebe3;
    }

    .starter h2 {
      margin-bottom: 36px;
      font-size: 40px;
      line-height: 1.2;
    }

    .starter-layout {
      display: grid;
      grid-template-columns:
        minmax(0, 1fr)
        minmax(0, 1.15fr);
      gap: 28px;
      align-items: stretch;
    }

    .starter-form,
    .starter-preview {
      padding: 42px;
      border-radius: 24px;
      background: #fffdf8;
      border: 1px solid #c8d0c8;
    }

    .starter-form {
      display: grid;
      align-content: start;
      gap: 26px;
    }

    .starter-form label {
      display: grid;
      gap: 12px;
    }

    .starter-preview {
      background: #17483c;
      color: #fff;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .starter-preview h3 {
      margin: 24px 0;
      font-size: 40px;
      line-height: 1.35;
      overflow-wrap: anywhere;
    }

    .starter-preview p {
      font-size: 20px;
      line-height: 1.8;
      color: #f1eee3;
      overflow-wrap: anywhere;
    }

    .starter-preview small {
      font-size: 16px;
      line-height: 1.5;
      color: #d7ddd6;
    }

    .starter-preview hr {
      width: 100%;
      border: 0;
      border-top: 1px solid #668276;
      margin: 24px 0;
    }

    .starter input {
      width: 100%;
      min-width: 0;
      min-height: 58px;
      font-size: 18px;
      padding: 14px 16px;
      border: 1px solid #9dac9e;
      border-radius: 10px;
    }

    .starter label {
      font-size: 18px;
    }

    [hidden] {
      display: none !important;
    }

    @media (min-width: 901px) {
      .card,
      .hero-card {
        height: 100%;
      }

      .info-grid + .card,
      .info-grid[style],
      .waitlist-box,
      .data-section .card[style] {
        height: auto;
      }

      .ticket .ticket-actions {
        padding-top: 8px;
      }
    }

    @media (max-width: 1100px) and (min-width: 901px) {
      .hero-grid {
        gap: 44px;
      }

      .hero-card {
        padding: 36px;
      }

      .section-head {
        gap: 44px;
      }

      .ticket {
        padding: 32px 26px;
      }

      .ticket-price {
        font-size: 35px;
      }

      .info-card,
